function updateUploadText(){const zhMap={I2VA:["首帧参考图","第一张为0秒首帧，可附加风格参考"],FL2VA:["首帧与尾帧","必须正好2张：首帧、尾帧"],L2VA:["尾帧参考图","第一张为视频最终画面"],Ref2VA:["完整参考图片","人物、产品、场景、风格等，最多12张"],Hybrid:["参考图片与可选关键帧","图片可作为人物、产品、场景、风格或可选首尾帧；下方可添加视频和声音"]},enMap={I2VA:["First-frame reference","Picture 1 is the frame at 0 seconds; optional style references may follow"],FL2VA:["First and last frames","Exactly two images: first frame, then last frame"],L2VA:["Last-frame reference","Picture 1 is the final video frame"],Ref2VA:["Complete reference images","Characters, products, scenes, and styles; up to 12 images"],Hybrid:["Reference images and optional keyframes","Images may define people, products, scenes, styles, or optional first/last frames; add video and audio below"]},map=uiLang==="en"?enMap:zhMap;if(map[mode]){$("#uploadTitle").textContent=map[mode][0];$("#uploadHelp").textContent=map[mode][1]}}
function total(){const t=(+$("#segmentCount").value||0)*(+$("#segmentSeconds").value||0);$("#totalSeconds").textContent=t.toFixed(Number.isInteger(t)?0:1);validateConfig()}$("#segmentCount").oninput=total;$("#segmentSeconds").oninput=total;
const drop=$("#dropzone"),input=$("#imageInput");drop.ondragover=e=>{e.preventDefault();drop.classList.add("drag")};drop.ondragleave=()=>drop.classList.remove("drag");drop.ondrop=e=>{e.preventDefault();drop.classList.remove("drag");addFiles([...e.dataTransfer.files])};input.onchange=()=>addFiles([...input.files]);
function referenceRoles(){return JSON.parse(localStorage.getItem("h3.referenceRoles")||'["人物参考","产品参考","场景参考","风格参考"]')}
function saveReferenceRoles(v){localStorage.setItem("h3.referenceRoles",JSON.stringify(v))}
function roleForIndex(i){if(mode==="FL2VA")return i===0?"首帧画面":"尾帧画面";if(mode==="I2VA")return i===0?"首帧画面":"人物参考";if(mode==="L2VA")return i===0?"尾帧画面":"人物参考";return referenceRoles()[i%Math.max(referenceRoles().length,1)]||"视觉参考"}
function addFiles(files){files.filter(f=>f.type.startsWith("image/")).slice(0,12-images.length).forEach(file=>{const r=new FileReader();r.onload=()=>{images.push({name:file.name,data:r.result,type:roleForIndex(images.length),description:""});renderImages();validateConfig()};r.readAsDataURL(file)});input.value=""}
function normalizedImage(item,i){if(!item.type){const legacy=item.role||roleForIndex(i),parts=legacy.split(/\s*[-:：]\s*/,2);item.type=referenceRoles().includes(parts[0])?parts[0]:roleForIndex(i);item.description=parts.length>1?parts[1]:(referenceRoles().includes(legacy)?"":legacy)}if(item.description===undefined)item.description="";return item}
function isFirstFrameRole(value=""){return /首帧|first[- ]frame/i.test(value)}
function isLastFrameRole(value=""){return /尾帧|last[- ]frame/i.test(value)}
const referenceRoleLabels={"首帧关键帧":"First-frame keyframe","尾帧关键帧":"Last-frame keyframe","人物参考":"Character reference","产品参考":"Product reference","场景参考":"Scene reference","风格参考":"Style reference","LOGO参考":"Logo reference","服装参考":"Wardrobe reference","道具参考":"Prop reference","视觉参考":"Visual reference"};
function imageRoleText(item,i){normalizedImage(item,i);const type=uiLang==="en"?(referenceRoleLabels[item.type]||item.type):item.type;return `${type}${item.description?`: ${item.description}`:""}`}
function roleOptions(selected){const base=[...(mode==="Hybrid"?["首帧关键帧","尾帧关键帧"]:[]),...referenceRoles()];if(selected&&!base.includes(selected))base.push(selected);return [...new Set(base)].map(x=>`<option value="${escapeHtml(x)}"${x===selected?' selected':''}>${escapeHtml(uiLang==="en"?(referenceRoleLabels[x]||x):x)}</option>`).join('')}
function renderImages(){const box=$("#previews");box.innerHTML="";images.forEach((raw,i)=>{const item=normalizedImage(raw,i),el=document.createElement("article");el.className="preview reference-card";el.innerHTML=`<div class="picture-media"><button class="picture-number" data-copy-label="${i}">Picture ${i+1}</button><img src="${item.data}" alt="Picture ${i+1}"></div><div class="reference-fields"><select class="reference-type" aria-label="Picture ${i+1} 用途">${roleOptions(item.type)}</select><input class="reference-description" value="${escapeHtml(item.description)}" placeholder="具体说明，例如：华人女销售、店外、LOGO"></div><div class="reference-tools"><button data-view="${i}">查看</button><button data-copy="${i}">复制图片</button><label class="replace-button">替换<input type="file" accept="image/*" data-replace="${i}"></label><button class="danger-button" data-delete="${i}">删除</button></div>`;el.querySelector(".reference-type").onchange=e=>{item.type=e.target.value;renderScriptReferencePicker();validateConfig()};el.querySelector(".reference-description").oninput=e=>{item.description=e.target.value;renderScriptReferencePicker()};el.querySelector("img").onclick=()=>openImagePreview(i);box.appendChild(el)});box.onclick=async e=>{const view=e.target.dataset.view,copy=e.target.dataset.copy,del=e.target.dataset.delete,label=e.target.dataset.copyLabel;if(view!==undefined)openImagePreview(+view);if(copy!==undefined)await copyImage(+copy);if(label!==undefined){await navigator.clipboard.writeText(`Picture ${+label+1}`);toast(`已复制 Picture ${+label+1} 编号`)}if(del!==undefined){images.splice(+del,1);renderImages();validateConfig();toast("参考图已删除，Picture 编号已自动更新")}};box.onchange=e=>{const idx=e.target.dataset.replace;if(idx===undefined||!e.target.files?.[0])return;const file=e.target.files[0],r=new FileReader();r.onload=()=>{images[+idx].data=r.result;images[+idx].name=file.name;renderImages();toast(`Picture ${+idx+1} 已替换`)};r.readAsDataURL(file)};renderScriptReferencePicker()}
let previewImageIndex=0;
function openImagePreview(i){previewImageIndex=i;const item=normalizedImage(images[i],i);$("#previewPictureLabel").textContent=`Picture ${i+1}`;$("#previewPictureInfo").textContent=imageRoleText(item,i);$("#previewLargeImage").src=item.data;$("#imagePreviewDialog").showModal()}
async function imageAsPng(data){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext("2d").drawImage(img,0,0);c.toBlob(b=>b?resolve(b):reject(Error("PNG conversion failed")),"image/png")};img.onerror=reject;img.src=data})}
async function copyImage(i){try{const blob=await imageAsPng(images[i].data);await navigator.clipboard.write([new ClipboardItem({"image/png":blob})]);toast(`Picture ${i+1} 图片已复制`)}catch{await navigator.clipboard.writeText(images[i].data);toast(`Picture ${i+1} 已复制为图片数据`)}}
$("#copyPreviewImage").onclick=()=>copyImage(previewImageIndex);$("#clearImages").onclick=()=>{images=[];renderImages();validateConfig()};
function audioRoleText(item){const role=item.role||"声音/节奏参考";return uiLang==="en"&&role==="声音/节奏参考"?"Voice / rhythm reference":role}
function mediaReferences(){return [...images.map((item,index)=>({kind:"Picture",index,item,label:`Picture ${index+1}`,detail:imageRoleText(item,index)})),...videos.map((item,index)=>({kind:"Video",index,item,label:`Video ${index+1}`,detail:videoRoleText(item)})),...audios.map((item,index)=>({kind:"Audio",index,item,label:`Audio ${index+1}`,detail:audioRoleText(item)}))]}
function insertMediaMention(kind,i,replaceAt=false,inputSelector="#scriptBrief",menuSelector="#pictureMentionMenu"){const el=$(inputSelector),tag=`<${kind} ${i+1}>`,start=el.selectionStart,end=el.selectionEnd,before=el.value.slice(0,start),after=el.value.slice(end);let cut=start;if(replaceAt){const match=before.match(/@[^@\s]*$/);if(match)cut=start-match[0].length}const prefix=el.value.slice(0,cut);el.value=prefix+tag+" "+after;el.focus();el.selectionStart=el.selectionEnd=prefix.length+tag.length+1;$(menuSelector).classList.add("hidden");updateReferenceHighlights()}
function focusMediaReference(kind,index){if(kind==="Picture")return openImagePreview(index);const selector=kind==="Video"?`[data-video-role="${index}"]`:`[data-audio-role="${index}"]`,target=$(selector)?.closest(kind==="Video"?".video-card":".audio-card");target?.scrollIntoView({behavior:"smooth",block:"center"});target?.classList.add("reference-pulse");setTimeout(()=>target?.classList.remove("reference-pulse"),900)}
function referenceChipHtml(ref,value){const used=new RegExp(`<${ref.kind}\\s+${ref.index+1}>`,"i").test(value),isPicture=ref.kind==="Picture",icon=ref.kind==="Video"?"▶":"♪";return `<span class="reference-mention-chip ${used?"is-used":""} ${isPicture?"":"media-chip"}"><button class="reference-chip-main" data-focus-kind="${ref.kind}" data-focus-index="${ref.index}" title="${used?(uiLang==="en"?"Referenced; show source":"已引用；定位素材"):(uiLang==="en"?"Show source":"定位参考素材")}">${isPicture?`<img src="${ref.item.data}" alt="">`:`<i class="reference-kind-icon ${ref.kind.toLowerCase()}">${icon}</i>`}<b>${ref.label}</b><small>${escapeHtml(ref.detail)}</small></button><button class="reference-chip-add" data-insert-kind="${ref.kind}" data-insert-index="${ref.index}" title="${uiLang==="en"?"Insert at cursor":"插入到光标位置"}">＋</button>${isPicture?`<span class="reference-hover-preview"><img src="${ref.item.data}" alt="${ref.label}"><strong>${ref.label}</strong><small>${escapeHtml(ref.detail)}</small></span>`:""}</span>`}
function renderReferenceChipBar(containerSelector,inputSelector){const box=$(containerSelector);if(!box)return;const value=$(inputSelector).value,refs=mediaReferences();if(!refs.length){box.innerHTML=`<small>${uiLang==="en"?"Add media, then type @ to reference it":"添加参考素材后，可输入 @ 选择引用"}</small>`;return}box.innerHTML=refs.map(ref=>referenceChipHtml(ref,value)).join("");box.onclick=e=>{const focus=e.target.closest('[data-focus-kind]'),add=e.target.closest('[data-insert-kind]');if(focus)focusMediaReference(focus.dataset.focusKind,+focus.dataset.focusIndex);if(add)insertMediaMention(add.dataset.insertKind,+add.dataset.insertIndex,false,inputSelector,inputSelector==="#idea"?"#ideaMentionMenu":"#pictureMentionMenu")}}
