function renderInlineMentionOverlay(inputSelector){const input=$(inputSelector),wrap=input.closest(".mention-wrap");if(!wrap)return;let layer=wrap.querySelector(".mention-highlight-layer"),content;if(!layer){layer=document.createElement("div");layer.className="mention-highlight-layer";layer.setAttribute("aria-hidden","true");content=document.createElement("div");content.className="mention-highlight-content";layer.appendChild(content);wrap.insertBefore(layer,wrap.querySelector(".mention-menu"));layer.onclick=e=>{const token=e.target.closest("[data-inline-kind]");if(token){e.preventDefault();e.stopPropagation();inlinePictureTooltip().classList.add("hidden");focusMediaReference(token.dataset.inlineKind,+token.dataset.inlineIndex)}};layer.onpointerover=e=>{const token=e.target.closest('[data-inline-kind="Picture"]');if(token)showInlinePictureTooltip(token)};layer.onpointerout=e=>{const token=e.target.closest('[data-inline-kind="Picture"]');if(token&&!token.contains(e.relatedTarget))inlinePictureTooltip().classList.add("hidden")}}else content=layer.firstElementChild;const style=getComputedStyle(input);layer.style.width=`${input.clientWidth}px`;layer.style.height=`${input.clientHeight}px`;for(const prop of ["fontFamily","fontSize","fontWeight","fontStyle","letterSpacing","lineHeight","textAlign","textIndent","textTransform","wordSpacing","tabSize"])content.style[prop]=style[prop];const source=input.value;let html="",last=0;for(const match of source.matchAll(/<(Picture|Video|Audio)\s+(\d+)>/gi)){html+=escapeHtml(source.slice(last,match.index));const kind=match[1][0].toUpperCase()+match[1].slice(1).toLowerCase(),idx=Number(match[2])-1,item=kind==="Picture"?images[idx]:kind==="Video"?videos[idx]:audios[idx];html+=item?`<span class="inline-picture-token inline-${kind.toLowerCase()}" data-inline-kind="${kind}" data-inline-index="${idx}"${kind==="Picture"?` data-inline-picture="${idx}"`:""}>${escapeHtml(match[0])}</span>`:`<span class="inline-picture-token missing">${escapeHtml(match[0])}</span>`;last=match.index+match[0].length}html+=escapeHtml(source.slice(last));content.innerHTML=html+"\n";content.style.transform=`translate(${-input.scrollLeft}px,${-input.scrollTop}px)`}
function renderScriptReferencePicker(){const menus=[$("#pictureMentionMenu"),$("#ideaMentionMenu")],refs=mediaReferences(),empty=uiLang==="en"?"No reference media yet":"还没有参考素材";updateReferenceHighlights();if(!refs.length){menus.forEach(menu=>menu.innerHTML=`<small>${empty}</small>`);return}const html=refs.map(ref=>`<button data-mention-kind="${ref.kind}" data-mention-index="${ref.index}">${ref.kind==="Picture"?`<img src="${ref.item.data}" alt="">`:`<i class="mention-kind-icon ${ref.kind.toLowerCase()}">${ref.kind==="Video"?"▶":"♪"}</i>`}<span><b>${ref.label}</b><small>${escapeHtml(ref.detail)}</small></span></button>`).join('');menus.forEach(menu=>menu.innerHTML=html);const bind=(menu,inputSelector)=>menu.onclick=e=>{const b=e.target.closest('[data-mention-kind]');if(b)insertMediaMention(b.dataset.mentionKind,+b.dataset.mentionIndex,true,inputSelector,`#${menu.id}`)};bind($("#pictureMentionMenu"),"#scriptBrief");bind($("#ideaMentionMenu"),"#idea")}
