const videoRoleLabels={reference_motion:["动作与运镜参考","Action and camera reference"],video_editing:["视频编辑源","Video editing source"],video_continuation:["视频续写源","Video continuation source"],temporal_structure:["剪辑与时间结构参考","Editing and temporal structure"]};
