function renderVideos(){const box=$("#videoList"),isEn=uiLang==="en";box.innerHTML=videos.map((x,i)=>`<article class="video-card"><div class="video-preview"><span class="video-number">Video ${i+1}</span><video src="${x.data||''}" controls preload="metadata" data-video-preview="${i}"></video></div><div class="video-card-fields"><b title="${escapeHtml(x.name)}">${escapeHtml(x.name)}</b><small class="media-meta" data-video-meta="${i}">${videoMetaText(x)}</small><select data-video-role="${i}" aria-label="Video ${i+1} ${isEn?'role':'用途'}">${videoRoleOptions(x.role||'reference_motion')}</select><input data-video-description="${i}" value="${escapeHtml(x.description||'')}" placeholder="${isEn?'Describe the motion, edit, continuation point, or timing to follow':'说明要参考的动作、剪辑、续写点或节奏'}"><div class="capture-row"><label><span>${isEn?'Frame time':'截帧时间'}</span><input type="number" min="0" step="0.01" value="${Number.isFinite(x.captureTime)?x.captureTime:0}" data-capture-time="${i}" aria-label="${isEn?'Capture time in seconds':'截帧时间（秒）'}"></label><button class="ghost" data-capture-frame="${i}">${isEn?'Capture as first frame':'截取为首帧'}</button></div></div><button class="ghost media-delete" data-video-delete="${i}">${isEn?'Delete':'删除'}</button></article>`).join('')||`<small>${isEn?'No video added. Hybrid supports up to 3 independently numbered Video references.':'尚未添加视频。Hybrid 最多支持3个独立编号的 Video 参考。'}</small>`;box.querySelectorAll('[data-video-preview]').forEach(video=>{const i=+video.dataset.videoPreview;video.onloadedmetadata=()=>{const item=videos[i];if(!item)return;item.duration=video.duration;item.width=video.videoWidth;item.height=video.videoHeight;const meta=box.querySelector(`[data-video-meta="${i}"]`),time=box.querySelector(`[data-capture-time="${i}"]`);if(meta)meta.textContent=videoMetaText(item);if(time&&Number.isFinite(video.duration))time.max=Math.max(0,video.duration-.001)}});box.onchange=e=>{const role=e.target.dataset.videoRole,time=e.target.dataset.captureTime;if(role!==undefined){videos[+role].role=e.target.value;renderScriptReferencePicker();validateConfig()}if(time!==undefined)videos[+time].captureTime=Math.max(0,+e.target.value||0)};box.oninput=e=>{const i=e.target.dataset.videoDescription;if(i!==undefined){videos[+i].description=e.target.value;renderScriptReferencePicker()}};box.onclick=async e=>{const del=e.target.closest('[data-video-delete]'),capture=e.target.closest('[data-capture-frame]');if(del){videos.splice(+del.dataset.videoDelete,1);renderVideos();validateConfig()}if(capture)await captureVideoFrame(+capture.dataset.captureFrame)};renderScriptReferencePicker()}
function waitForMedia(media,event){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(Error("Media preview timed out"))},5000),done=()=>{cleanup();resolve()},fail=()=>{cleanup();reject(Error("Media preview is unavailable"))},cleanup=()=>{clearTimeout(timer);media.removeEventListener(event,done);media.removeEventListener("error",fail)};media.addEventListener(event,done,{once:true});media.addEventListener("error",fail,{once:true})})}
async function captureVideoFrame(i){const item=videos[i],video=$(`[data-video-preview="${i}"]`),input=$(`[data-capture-time="${i}"]`);if(!item?.data||!video)return toast(uiLang==="en"?"This video is unavailable; add the file again":"视频文件不可用，请重新添加");try{if(video.readyState<1)await waitForMedia(video,"loadedmetadata");if(video.readyState<2)await waitForMedia(video,"loadeddata");const max=Number.isFinite(video.duration)?Math.max(0,video.duration-.001):0,time=Math.min(Math.max(0,+input.value||0),max);item.captureTime=time;if(Math.abs(video.currentTime-time)>.001){video.currentTime=time;await waitForMedia(video,"seeked")}const canvas=document.createElement("canvas");canvas.width=video.videoWidth;canvas.height=video.videoHeight;if(!canvas.width||!canvas.height)throw Error("Video frame is unavailable");canvas.getContext("2d").drawImage(video,0,0);const frame={name:`${item.name.replace(/\.[^.]+$/,"")}-frame-${time.toFixed(2)}s.png`,data:canvas.toDataURL("image/png"),type:"首帧关键帧",description:uiLang==="en"?`Captured from Video ${i+1} at ${time.toFixed(2)}s`:`从 Video ${i+1} 的 ${time.toFixed(2)} 秒截取`},existing=images.findIndex((x,n)=>isFirstFrameRole(normalizedImage(x,n).type));if(existing>=0)images[existing]={...images[existing],...frame};else{if(images.length>=12)throw Error(uiLang==="en"?"The 12-image limit has been reached":"参考图已达到12张上限");images.push(frame)}renderImages();validateConfig();toast(uiLang==="en"?`Captured ${time.toFixed(2)}s as Picture ${existing>=0?existing+1:images.length} first frame`:`已将 ${time.toFixed(2)} 秒截取为 Picture ${existing>=0?existing+1:images.length} 首帧`)}catch(error){toast(uiLang==="en"?`Frame capture failed: ${error.message}`:`截帧失败：${error.message}`)}}
