function parseSegments(){segments=[];const re=/===\s*Segment\s+\d+[^=]*===/gi,matches=[...fullOutput.matchAll(re)];if(matches.length){matches.forEach((m,i)=>segments.push(fullOutput.slice(m.index,matches[i+1]?.index??fullOutput.length).trim()))}renderSegmentTabs()}
